import type { JSX } from "@solidjs/web";
import { usePart, usePrimitive } from "@ui-sdk/solid/primitive";
import { createContext, createUniqueId, merge, omit, useContext } from "solid-js";

import { itemGroupPrimitive } from "./item-primitive";
import { Separator, type SeparatorProps } from "./separator";

import "./item.css";

/**
 * Item, opencode console's list row (the Controls and Extensions rows, the
 * Activity log, Billing's "One-time credits · Add credits") with shadcn's part
 * names:
 *
 *   <ItemGroup>
 *     <Item variant="outline">
 *       <ItemMedia variant="icon"><CoinIcon /></ItemMedia>
 *       <ItemContent>
 *         <ItemTitle>One-time credits</ItemTitle>
 *         <ItemDescription>Purchase additional workspace credits</ItemDescription>
 *       </ItemContent>
 *       <ItemActions><Button size="small">Add credits</Button></ItemActions>
 *     </Item>
 *   </ItemGroup>
 *
 * The parts are plain markup and the look lives in `item.css`. `href` renders
 * the row as a link, with the console's hover overlay.
 *
 * ItemGroup is a `role="list"`; each Item in it is a list item. Pass `roving`
 * to make its link rows one Tab stop with Up, Down, Home and End between them
 * (ui-sdk's roving focus, see `item-primitive.ts`). Without it, every link row
 * is its own Tab stop, as on a page of links.
 */

type ItemGroupContextValue = { roving: boolean };

// `null` default: an Item outside an ItemGroup is valid (Solid 2 throws on a
// missing provider when the context has no default).
const ItemGroupContext = createContext<ItemGroupContextValue | null>(null);

export type ItemVariant = "default" | "outline" | "muted";

export type ItemSize = "default" | "sm";

export type ItemProps = JSX.AnchorHTMLAttributes<HTMLElement> & {
  /** Defaults to `default`: no fill or border. */
  variant?: ItemVariant;
  /** Defaults to `default` (12px 16px). `sm` is the console's 6px 8px log row. */
  size?: ItemSize;
  /** Renders the row as an `<a>`. Don't put other links or buttons inside it. */
  href?: string;
};

export function Item(props: ItemProps) {
  const group = useContext(ItemGroupContext);
  const rest = omit(props, "variant", "size");
  const look = {
    get "data-variant"() {
      return props.variant ?? "default";
    },
    get "data-size"() {
      return props.size ?? "default";
    },
  };

  if (props.href === undefined) {
    return (
      <div
        role={group ? "listitem" : undefined}
        {...(rest as JSX.HTMLAttributes<HTMLDivElement>)}
        {...look}
        data-slot="item"
      />
    );
  }

  // A roving row needs its own key: without one, every row is the same part
  // (key "") and they all keep tabindex 0.
  const rowKey = createUniqueId();
  const link = group?.roving ? (
    usePart(itemGroupPrimitive, "item", () => ({ value: rowKey }), merge(rest, look) as never, "a")
  ) : (
    <a {...(rest as JSX.AnchorHTMLAttributes<HTMLAnchorElement>)} {...look} data-slot="item" />
  );

  // A link keeps its role, so a list item wraps it (`display: contents`).
  return group ? (
    <div role="listitem" data-slot="item-listitem">
      {link}
    </div>
  ) : (
    link
  );
}

export type ItemGroupProps = JSX.HTMLAttributes<HTMLDivElement> & {
  /**
   * One Tab stop for the group's link rows, with Up, Down, Home and End
   * between them. Read once, when the group renders. Defaults to `false`.
   */
  roving?: boolean;
  /** With `roving`, wrap from the last row to the first, and back. */
  loop?: boolean;
};

/** A `role="list"` of Items, 8px apart; ItemSeparators join them instead. */
export function ItemGroup(props: ItemGroupProps) {
  const rest = omit(props, "roving", "loop");

  if (!props.roving) {
    return (
      <ItemGroupContext value={{ roving: false }}>
        <div role="list" {...rest} data-slot="item-group" />
      </ItemGroupContext>
    );
  }

  const handle = usePrimitive(itemGroupPrimitive, () => ({ loop: props.loop }));

  return (
    <ItemGroupContext value={{ roving: true }}>
      {usePart(handle, "root", undefined, rest as never, "div")}
    </ItemGroupContext>
  );
}

export type ItemSeparatorProps = SeparatorProps;

/** The hairline between Items in a group. Decorative, so the list stays a list. */
export function ItemSeparator(props: ItemSeparatorProps) {
  return <Separator decorative {...props} data-item-separator="" />;
}

export type ItemMediaVariant = "default" | "icon" | "image";

export type ItemMediaProps = JSX.HTMLAttributes<HTMLDivElement> & {
  /**
   * `default` holds an Avatar or a status chip as is; `icon` is the console's
   * raised 32px tile for a 16px icon; `image` crops an <img> to 32px.
   */
  variant?: ItemMediaVariant;
};

export function ItemMedia(props: ItemMediaProps) {
  const rest = omit(props, "variant");

  return <div {...rest} data-slot="item-media" data-variant={props.variant ?? "default"} />;
}

export type ItemContentProps = JSX.HTMLAttributes<HTMLDivElement>;

/** Title and description; takes the row's free width. */
export function ItemContent(props: ItemContentProps) {
  return <div {...props} data-slot="item-content" />;
}

export type ItemTitleProps = JSX.HTMLAttributes<HTMLDivElement>;

/** The row's name, 530 weight. A Badge beside it sits 8px away. */
export function ItemTitle(props: ItemTitleProps) {
  return <div {...props} data-slot="item-title" />;
}

export type ItemDescriptionProps = JSX.HTMLAttributes<HTMLParagraphElement>;

/** Muted text under the title, clamped to two lines. */
export function ItemDescription(props: ItemDescriptionProps) {
  return <p {...props} data-slot="item-description" />;
}

export type ItemActionsProps = JSX.HTMLAttributes<HTMLDivElement>;

/** Buttons or a chevron at the end of the row, 8px apart. */
export function ItemActions(props: ItemActionsProps) {
  return <div {...props} data-slot="item-actions" />;
}

export type ItemHeaderProps = JSX.HTMLAttributes<HTMLDivElement>;

/** A full-width line above the row's media and content. */
export function ItemHeader(props: ItemHeaderProps) {
  return <div {...props} data-slot="item-header" />;
}

export type ItemFooterProps = JSX.HTMLAttributes<HTMLDivElement>;

/** A full-width line below the row's media and content. */
export function ItemFooter(props: ItemFooterProps) {
  return <div {...props} data-slot="item-footer" />;
}

import { createRovingFocus, definePrimitive, selects } from "@ui-sdk/core";

/**
 * Item Group's opt-in keyboard behaviour, on `@ui-sdk/core` so every framework
 * binding shares it. A plain ItemGroup is a `role="list"` where each link row
 * is its own Tab stop. With this primitive the link rows become one Tab stop:
 * Up and Down move between them, Home and End jump to the ends, and Tab moves
 * on to the focused row's ItemActions, then out of the group.
 *
 * It follows ui-sdk's Timeline, a list whose items rove the same way: the
 * group keeps `role="list"`, items keep their own semantics (a link stays a
 * link), and arrows only move when the row itself has focus, so a control in
 * ItemActions keeps its own keys.
 *
 * Only rows that are links join (`slot: "item"`). Static rows, separators and
 * the buttons inside a row are left alone.
 */

export type ItemGroupOptions = {
  /** Whether moving past the last row wraps to the first, and back. Defaults to `false`. */
  loop?: boolean;
};

export const itemGroupPrimitive = definePrimitive({
  name: "item-group",
  options: { loop: "boolean" },
  state: (options: ItemGroupOptions) => ({
    loop: !!options.loop,
    stop: null as string | null,
  }),
  sync: (options: ItemGroupOptions) => ({ loop: !!options.loop }),
  api: (context) => {
    const roving = createRovingFocus(context, {
      slot: "item",
      key: "stop",
      loop: () => context.store.get().loop,
    });

    return {
      roving,
      keydown(event: KeyboardEvent, el: HTMLElement) {
        if (event.defaultPrevented || event.target !== el || event.shiftKey) return;
        roving.keydown(event, el);
      },
    };
  },
  slots: (slot) => ({
    root: slot({
      role: "list",
      selects: selects({ stop: [] }),
    }),
    // Each row needs its own `value`: a part's key is its `id` or `value`, and
    // rows without one all share the key "" (one part, one tabindex). The
    // adapters' generated parts fill an "id" prop; a hand-written `usePart`
    // must pass one, as Item does with createUniqueId / useId.
    item: slot<{ value?: string }>({
      props: { value: "id" },
      selects: selects({ stop: ({ key }) => [key, null] }),
      // The row keeps item.css's slot, so every binding styles it unchanged.
      attrs: (state, part) => ({
        "data-slot": "item",
        tabindex: part.api.roving.tabIndex(state, part),
      }),
      on: {
        keydown: (event, { el, api }) => {
          if (el) api.keydown(event as KeyboardEvent, el);
        },
      },
      bind: (el, part) => part.api.roving.bind(el, part),
    }),
  }),
});

/*
 * Item, ported from opencode console's list rows. The console is hosted and
 * its source is not in the opencode checkout, so the rules were read from its
 * live stylesheet and renamed to Kitsaas slots:
 *
 *   .control-list                       →  [data-slot="item-group"]
 *   .control-list-row                   →  [data-slot="item"][data-variant="outline"]
 *   .control-list-row:hover             →  a link item's :hover (every variant)
 *   .extensions-item                    →  [data-slot="item"] (radius, gap, flex)
 *   .billing-inset                      →  [data-slot="item"][data-variant="muted"]
 *   .activity-request-row (+ shared
 *     .activity-*-row padding/radius)   →  [data-slot="item"][data-size="sm"]
 *   .activity-*-row:focus-visible       →  [data-slot="item"]:focus-visible
 *   .extensions-layout .control-list-icon
 *                                       →  [data-slot="item-media"][data-variant="icon"]
 *   .resource-controls-card .control-list-logo > *
 *                                       →  [data-slot="item-media"][data-variant="image"]
 *   .resource-control-text              →  [data-slot="item-content"]
 *   .resource-control-subtitle          →  [data-slot="item-description"]
 *   .billing-row (gap 8px)              →  [data-slot="item-actions"]
 *   .summary-row-chevron                →  an svg in [data-slot="item-actions"]
 *   .controls-layout (13px / 20px)      →  the item's type
 *   .resource-controls-card > li + li   →  a group with ItemSeparators (no gap)
 *
 * Every colour is a --v2-* token already, except two legacy aliases that
 * .resource-controls-card reads, mapped to the --v2-* they alias in
 * src/theme.css:
 *
 *   --color-surface      →  --v2-background-bg-layer-01
 *   --color-border-muted →  --v2-border-border-muted
 *
 * The separator itself is Kitsaas's Separator (opencode's Divider, the same
 * 1px × scaleY(0.5) hairline the console draws in .billing-panel hr).
 *
 * Kitsaas additions, marked below: `flex-wrap` so ItemHeader and ItemFooter
 * take a full line (shadcn's layout); ItemTitle's 530 weight and the 8px gap
 * for a Badge beside it (the console's .activity-request-model and
 * .billing-shortcut weight); ItemDescription's two-line clamp and top-aligned
 * media beside a description (shadcn); and the
 * `display: contents` list item that wraps a link row in an ItemGroup.
 *
 * The rule set is attribute driven, so the React, Vue, Svelte and web
 * bindings reuse this file unchanged.
 */

@layer components {
  [data-slot="item-group"] {
    display: flex;
    flex-direction: column;
    gap: 8px;
    min-width: 0;
  }

  /* Rows joined by hairlines, like .resource-controls-card. */
  [data-slot="item-group"]:has(> [data-item-separator]) {
    gap: 0;
  }

  [data-slot="item-listitem"] {
    display: contents;
  }

  [data-slot="item"] {
    box-sizing: border-box;
    display: flex;
    flex-wrap: wrap; /* Kitsaas addition: room for ItemHeader / ItemFooter. */
    align-items: center;
    gap: 16px;
    min-width: 0;
    padding: 12px 16px;
    border-radius: 6px;
    background: transparent;
    color: var(--v2-text-text-base);
    font-family: var(--v2-font-family-sans, inherit);
    font-size: 13px;
    font-weight: 440;
    line-height: 20px;
    letter-spacing: -0.04px;
    text-align: left;
    text-decoration: none;
  }

  [data-slot="item"][data-variant="outline"] {
    background: var(--v2-background-bg-layer-01);
    box-shadow: inset 0 0 0 0.5px var(--v2-border-border-muted);
  }

  [data-slot="item"][data-variant="muted"] {
    background: var(--v2-background-bg-layer-02);
    box-shadow: inset 0 0 0 0.5px var(--v2-border-border-muted);
  }

  [data-slot="item"][data-size="sm"] {
    gap: 12px;
    padding: 6px 8px;
  }

  a[data-slot="item"][href] {
    cursor: pointer;
  }

  a[data-slot="item"][href]:hover {
    background-image: linear-gradient(
      var(--v2-overlay-simple-overlay-hover),
      var(--v2-overlay-simple-overlay-hover)
    );
  }

  [data-slot="item"]:focus-visible {
    outline: 2px solid var(--v2-border-border-focus);
    outline-offset: 2.5px;
  }

  [data-slot="item-media"] {
    display: flex;
    flex: none;
    align-items: center;
    justify-content: center;
    gap: 8px;
  }

  /* Kitsaas addition (shadcn): media aligns to the title when there's a description. */
  [data-slot="item"]:has(> [data-slot="item-content"] > [data-slot="item-description"])
    > [data-slot="item-media"] {
    align-self: flex-start;
  }

  [data-slot="item-media"][data-variant="icon"] {
    width: 32px;
    height: 32px;
    border-radius: 6px;
    background: var(--v2-background-bg-base);
    box-shadow: var(--v2-elevation-raised);
    color: var(--v2-icon-icon-muted);
  }

  [data-slot="item-media"][data-variant="icon"] > svg {
    width: 16px;
    height: 16px;
    flex: none;
  }

  [data-slot="item-media"][data-variant="image"] {
    width: 32px;
    height: 32px;
    overflow: hidden;
    border-radius: 6px;
  }

  [data-slot="item-media"][data-variant="image"] > img {
    width: 100%;
    height: 100%;
    object-fit: cover;
  }

  [data-slot="item-content"] {
    display: flex;
    flex: 1;
    flex-direction: column;
    min-width: 0;
  }

  [data-slot="item-title"] {
    display: flex;
    align-items: center;
    gap: 8px; /* Kitsaas addition: a Badge beside the title. */
    min-width: 0;
    color: var(--v2-text-text-base);
    font-weight: 530; /* Kitsaas addition, from .activity-request-model. */
  }

  [data-slot="item-description"] {
    margin: 0;
    color: var(--v2-text-text-muted);
    text-wrap: pretty;
    /* Kitsaas addition: shadcn's two-line clamp. */
    display: -webkit-box;
    -webkit-box-orient: vertical;
    -webkit-line-clamp: 2;
    line-clamp: 2;
    overflow: hidden;
  }

  [data-slot="item-actions"] {
    display: flex;
    flex: none;
    align-items: center;
    gap: 8px;
  }

  [data-slot="item-actions"] > svg {
    width: 16px;
    height: 16px;
    color: var(--v2-icon-icon-muted);
  }

  /* Kitsaas addition (shadcn's layout): full-width lines above and below. */
  [data-slot="item-header"],
  [data-slot="item-footer"] {
    display: flex;
    flex-basis: 100%;
    align-items: center;
    justify-content: space-between;
    gap: 8px;
  }
}
